// Normalized ingest contract. Every acquisition path emits this shape.
// audio_ref and meeting_id are interpolated into the ffmpeg command line by the
// next node, so both are constrained here: anything that could break out of the
// quoted shell argument is rejected instead of being passed through.
//
// Optional fields a caller may supply when it knows them:
//   direction  'inbound' | 'outbound'   (omitted = unknown; adapters never guess it)
//   crm_refs   { contact_id, deal_id, company_id }   existing CRM record ids the
//              call should be associated to. Read by Build CRM Request.
const DEMO = '/data/recordings/sample-call.m4a';
const i = $input.first().json || {};

const audioRef = String(i.path || i.filePath || i.audio_ref || DEMO);
// Inside a double-quoted sh argument only " $ ` and \ are special. Control
// characters (newline, NUL) are rejected too. & ; | < > are inert there and are
// common in signed recording URLs, so they are allowed.
if (/["`$\\\x00-\x1f\x7f]/.test(audioRef)) {
  throw new Error('audio_ref contains characters that are not allowed in a file reference.');
}

const rawId = String(i.meeting_id || ('local-' + Date.now()));
const meetingId = rawId.replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 80) || ('local-' + Date.now());

const channels = i.channels === 'dual' ? 'dual' : 'mono'; // 'dual' = per-leg channels, no diarization needed

const start = i.start_time ? new Date(i.start_time) : new Date();
if (isNaN(start.getTime())) throw new Error('start_time is not a valid date: ' + String(i.start_time).slice(0, 40));

const direction = ['inbound', 'outbound'].find((d) => d === String(i.direction || '').toLowerCase()) || '';

const crmRefs = {};
for (const key of ['contact_id', 'deal_id', 'company_id']) {
  const id = String((i.crm_refs && typeof i.crm_refs === 'object' && i.crm_refs[key]) || '');
  if (/^[A-Za-z0-9_-]{1,64}$/.test(id)) crmRefs[key] = id;
}

return [{ json: {
  audio_ref:    audioRef,
  meeting_id:   meetingId,
  participants: Array.isArray(i.participants) ? i.participants : [],
  start_time:   start.toISOString(),
  duration_sec: Number(i.duration_sec) || 0,
  channels,
  direction,
  crm_refs:     crmRefs,
  source:       i.source || 'folder' } }];

// ===== RUNTIME CONFIG - the only node you edit =====
// Providers auto-select on key presence: keys -> cloud, no keys -> local.
// $env access can be disabled in some n8n installs; hardcode below if so.
const env = (k) => { try { return $env[k] || ''; } catch (e) { return ''; } };

const CFG = {
  openai_key:    env('OPENAI_API_KEY'),
  anthropic_key: env('ANTHROPIC_API_KEY'),
  deepgram_key:  env('DEEPGRAM_API_KEY'),
  ollama_url:    env('OLLAMA_URL')  || 'http://host.docker.internal:11434',
  whisper_url:   env('WHISPER_URL') || 'http://host.docker.internal:8000',
  openai_model:    env('OPENAI_MODEL')    || 'gpt-4o-mini',
  anthropic_model: env('ANTHROPIC_MODEL') || 'claude-sonnet-4-20250514',
  ollama_model:    env('OLLAMA_MODEL')    || 'qwen2.5:7b',
  crm_provider:  (env('CRM_PROVIDER') || 'webhook').toLowerCase(),
  crm_webhook:   env('CRM_WEBHOOK_URL'),
  crm_token:     env('CRM_TOKEN'),
  crm_base:      env('CRM_BASE_URL'),
  monday_board:  env('MONDAY_BOARD_ID'),
  monday_group:  env('MONDAY_GROUP_ID') || '',
  min_conf:      Number(env('MIN_CONFIDENCE') || 0.6)
};

// --- provider election -------------------------------------------------
let llm = 'ollama';
if (CFG.openai_key) llm = 'openai';
else if (CFG.anthropic_key) llm = 'anthropic';

let stt = 'local';
if (CFG.deepgram_key) stt = 'deepgram';      // cloud: diarization and per-channel transcripts

const ctx = $input.first().json;
return [{ json: { ...ctx, _cfg: { ...CFG, llm_provider: llm, stt_provider: stt },
  _routing: { llm, stt, crm: CFG.crm_provider,
    note: `LLM=${llm} STT=${stt} CRM=${CFG.crm_provider}` } }}];

// Build STT request. Cloud STT needs the audio bytes; local takes a path.
// The previous node (Execute Command) outputs only { exitCode, stderr, stdout },
// so the call context is read from Runtime Config, not from $json.
const ctx = $('Runtime Config').first().json;
const c = ctx._cfg;
const wav = '/data/work/' + ctx.meeting_id + '.wav';
const dual = ctx.channels === 'dual';

if (c.stt_provider === 'deepgram') {
  // dual: one transcript per channel (exact speakers). mono: diarization.
  return [{ json: { _stt: { mode: 'binary', file: wav,
    url: 'https://api.deepgram.com/v1/listen?model=nova-3&smart_format=true&punctuate=true&' +
         (dual ? 'multichannel=true' : 'diarize=true'),
    headers: { Authorization: 'Token ' + c.deepgram_key, 'Content-Type': 'audio/wav' } } } }];
}
return [{ json: { _stt: { mode: 'json' },
  _req: { url: c.whisper_url + '/transcribe', headers: { 'Content-Type': 'application/json' },
    body: { path: wav, meeting_id: ctx.meeting_id, channels: ctx.channels, diarize: !dual } } } }];

// Flatten every provider's response into ONE shape:
// { meeting_id, segments: [{speaker,start,end,text}] }
const r = $input.first().json;
const ctx = $('Runtime Config').first().json;
let segments = [];

if (Array.isArray(r.segments)) {
  segments = r.segments;                                   // local service - already normalized
} else if (r.results?.channels) {                          // Deepgram
  const channels = r.results.channels;
  // multichannel: one entry per audio channel, labelled like the local service
  // (left = REP, right = PROSPECT). Otherwise the diarized speaker index.
  const LEGS = ['REP', 'PROSPECT'];
  const words = channels.flatMap((ch, idx) => (ch.alternatives?.[0]?.words || []).map((w) => ({ ...w,
    _spk: channels.length > 1 ? (LEGS[idx] || 'CHANNEL_' + idx)
        : w.speaker !== undefined ? 'SPEAKER_' + w.speaker : 'SPEAKER' })));
  if (channels.length > 1) words.sort((a, b) => a.start - b.start);
  let cur = null;
  for (const w of words) {
    if (!cur || cur.speaker !== w._spk) {
      if (cur) segments.push(cur);
      cur = { speaker: w._spk, start: w.start, end: w.end, text: '' };
    }
    cur.text += (cur.text ? ' ' : '') + (w.punctuated_word || w.word);
    cur.end = w.end;
  }
  if (cur) segments.push(cur);
  if (!segments.length) {
    const text = channels.map((ch) => ch.alternatives?.[0]?.transcript || '').join(' ').trim();
    if (text) segments = [{ speaker: 'SPEAKER', start: 0, end: 0, text }];
  }
}

if (!segments.length) throw new Error('Transcription returned no segments.');
return [{ json: { meeting_id: ctx.meeting_id, segments } }];

// Map-reduce. Small models degrade over long context; even large ones lose recall.
const r = $input.first().json;
const segs = r.segments || [];
const MAX = 1200;
const chunks = []; let cur = [], words = 0;
for (const s of segs) {
  const w = (s.text || '').split(/\s+/).length;
  if (words + w > MAX && cur.length) {
    chunks.push(cur);
    cur = [cur[cur.length - 1]];                 // 1-turn overlap
    words = (cur[0].text || '').split(/\s+/).length;
  }
  cur.push(s); words += w;
}
if (cur.length) chunks.push(cur);
return chunks.map((c, i) => ({ json: { chunk_id: i, chunk_total: chunks.length,
  meeting_id: r.meeting_id,
  text: c.map(s => `${s.speaker || 'SPEAKER'}: ${s.text}`).join('\n') } }));

// One request builder, three providers. Downstream never knows which ran.
const c = $('Runtime Config').first().json._cfg;
const SCHEMA = {"type": "object", "properties": {"account": {"type": "object", "properties": {"name": {"type": "string"}, "domain": {"type": "string"}}, "required": ["name"]}, "attendees": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "role": {"type": "string"}, "side": {"type": "string", "enum": ["rep", "prospect", "unknown"]}}, "required": ["name", "side"]}}, "qualification": {"type": "object", "properties": {"budget_signals": {"type": "array", "items": {"type": "string"}}, "authority": {"type": "array", "items": {"type": "string"}}, "need": {"type": "array", "items": {"type": "string"}}, "timeline": {"type": "string"}, "metrics_mentioned": {"type": "array", "items": {"type": "string"}}}}, "pain_points": {"type": "array", "items": {"type": "object", "properties": {"paraphrase": {"type": "string"}, "verbatim_quote": {"type": "string"}, "severity": {"type": "string", "enum": ["low", "medium", "high", "unknown"]}}, "required": ["paraphrase"]}}, "competitors_mentioned": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "context": {"type": "string"}}, "required": ["name"]}}, "objections": {"type": "array", "items": {"type": "object", "properties": {"objection": {"type": "string"}, "rep_response": {"type": "string"}, "resolved": {"type": "boolean"}}, "required": ["objection"]}}, "rep_commitments": {"type": "array", "items": {"type": "object", "properties": {"commitment": {"type": "string"}, "due": {"type": "string"}, "explicit": {"type": "boolean"}}, "required": ["commitment"]}}, "next_steps": {"type": "array", "items": {"type": "object", "properties": {"action": {"type": "string"}, "owner": {"type": "string"}, "due_date": {"type": "string"}}, "required": ["action"]}}, "risk_flags": {"type": "array", "items": {"type": "string"}}, "recommended_stage": {"type": "string"}, "confidence": {"type": "number"}}, "required": ["account", "pain_points", "rep_commitments", "next_steps", "confidence"]};
const SYSTEM = "You extract structured sales-call intelligence from a transcript chunk.\nRULES:\n1. Extract ONLY what is explicitly supported by the transcript. Never infer or invent.\n2. If a field has no support in this chunk, return an empty array or empty string.\n3. rep_commitments = things the SALES REP promised to do (send pricing, intro an SE, follow up by a date). Highest-value field. Do not confuse with prospect actions.\n4. verbatim_quote must be an exact substring of the transcript.\n5. confidence = honest 0..1 confidence for THIS chunk. Low is fine and expected.\nReturn JSON only.";
const user = `Transcript chunk ${$json.chunk_id + 1} of ${$json.chunk_total}:\n\n${$json.text}`;

let _req;
if (c.llm_provider === 'openai') {
  _req = { url: 'https://api.openai.com/v1/chat/completions',
    headers: { Authorization: 'Bearer ' + c.openai_key, 'Content-Type': 'application/json' },
    body: { model: c.openai_model, temperature: 0,
      response_format: { type: 'json_schema',
        json_schema: { name: 'call_extraction', schema: SCHEMA } },
      messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }] } };
} else if (c.llm_provider === 'anthropic') {
  // Anthropic has no response_format; force a tool call to get schema-valid JSON.
  _req = { url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': c.anthropic_key, 'anthropic-version': '2023-06-01',
               'Content-Type': 'application/json' },
    body: { model: c.anthropic_model, max_tokens: 4096, temperature: 0, system: SYSTEM,
      messages: [{ role: 'user', content: user }],
      tools: [{ name: 'record_extraction', description: 'Return the structured extraction',
                input_schema: SCHEMA }],
      tool_choice: { type: 'tool', name: 'record_extraction' } } };
} else {
  _req = { url: c.ollama_url + '/api/chat',
    headers: { 'Content-Type': 'application/json' },
    body: { model: c.ollama_model, stream: false, format: SCHEMA,
      options: { temperature: 0, num_ctx: 8192 },
      messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }] } };
}
return [{ json: { ...$json, _req } }];

// Flatten Ollama / OpenAI / Anthropic responses to one shape.
const r = $input.first().json;
let extraction = null, err = null, txt = null;
try {
  if (Array.isArray(r.content)) {                                  // Anthropic
    const tu = r.content.find(c => c.type === 'tool_use');
    if (tu) extraction = tu.input;
    else txt = r.content.map(c => c.text).filter(Boolean).join('');
  } else if (r.choices?.[0]?.message?.content) {                    // OpenAI
    txt = r.choices[0].message.content;
  } else if (r.message?.content) {                                  // Ollama
    txt = r.message.content;
  } else if (r.response) {
    txt = r.response;
  }
  if (!extraction && txt) {
    const s = txt.indexOf('{'), e = txt.lastIndexOf('}');
    extraction = JSON.parse(s >= 0 ? txt.slice(s, e + 1) : txt);
  }
} catch (e) { err = String(e); }

return [{ json: { chunk_id: $('Loop Over Chunks').item.json.chunk_id,
  extraction: extraction || { _parse_error: err || 'no content', _raw: txt } } }];

// Reduce chunk extractions -> one canonical record. CRM-neutral by design.
const items = $input.all().map(i => i.json).filter(Boolean);
const ctx = $('Runtime Config').first().json;
const cfg = ctx._cfg;

const good = items.filter(i => i.extraction && !i.extraction._parse_error);
const dedupe = (arr, key) => { const seen = new Set(), out = [];
  for (const x of arr) {
    const k = String(typeof x === 'string' ? x : (x[key] ?? JSON.stringify(x))).toLowerCase().trim();
    if (k && !seen.has(k)) { seen.add(k); out.push(x); } }
  return out; };
const gather = (path, key) => dedupe(good.flatMap(i => {
  const v = path.split('.').reduce((o, p) => (o ?? {})[p], i.extraction);
  return Array.isArray(v) ? v : []; }), key);

const names = good.map(i => i.extraction?.account?.name).filter(Boolean);
const confs = good.map(i => Number(i.extraction?.confidence)).filter(n => !isNaN(n));
const avg = confs.length ? confs.reduce((a,b) => a+b, 0) / confs.length : 0;
const parseRate = items.length ? good.length / items.length : 0;

return [{ json: {
  meeting_id: ctx.meeting_id, source: ctx.source, start_time: ctx.start_time,
  account: { name: names.sort((a,b) =>
      names.filter(v=>v===b).length - names.filter(v=>v===a).length)[0] || '' },
  attendees:             gather('attendees','name'),
  pain_points:           gather('pain_points','paraphrase'),
  competitors_mentioned: gather('competitors_mentioned','name'),
  objections:            gather('objections','objection'),
  rep_commitments:       gather('rep_commitments','commitment'),
  next_steps:            gather('next_steps','action'),
  risk_flags:            gather('risk_flags'),
  qualification: {
    budget_signals: gather('qualification.budget_signals'),
    authority: gather('qualification.authority'),
    need: gather('qualification.need'),
    metrics_mentioned: gather('qualification.metrics_mentioned'),
    timeline: good.map(i => i.extraction?.qualification?.timeline).filter(Boolean)[0] || '' },
  recommended_stage: good.map(i => i.extraction?.recommended_stage).filter(Boolean)[0] || '',
  confidence: Number((avg * parseRate).toFixed(3)),
  _min_confidence: cfg.min_conf,
  provenance: { llm_provider: cfg.llm_provider, stt_provider: cfg.stt_provider,
    model: cfg.llm_provider === 'openai' ? cfg.openai_model
         : cfg.llm_provider === 'anthropic' ? cfg.anthropic_model : cfg.ollama_model,
    chunks_total: items.length, chunks_parsed: good.length,
    chunks_failed: items.length - good.length,
    generated_at: new Date().toISOString() } } }];

// CRM ADAPTER - canonical record -> provider payload.
// Default 'webhook' posts the canonical record anywhere: works with ANY CRM,
// including ones not implemented here. Add a branch to support a new system.
const rec = $json;
const c = $('Runtime Config').first().json._cfg;

const lines = [];
if (rec.rep_commitments?.length) lines.push('COMMITMENTS MADE BY REP:',
  ...rec.rep_commitments.map(x => '- ' + x.commitment + (x.due ? ' (due ' + x.due + ')' : '')), '');
if (rec.next_steps?.length) lines.push('NEXT STEPS:',
  ...rec.next_steps.map(x => '- ' + x.action + ' [' + (x.owner || 'unassigned') + ']'), '');
if (rec.objections?.length) lines.push('OBJECTIONS:',
  ...rec.objections.map(x => '- ' + x.objection), '');
if (rec.pain_points?.length) lines.push('PAIN POINTS:',
  ...rec.pain_points.map(x => '- ' + x.paraphrase), '');
if (rec.competitors_mentioned?.length)
  lines.push('COMPETITORS: ' + rec.competitors_mentioned.map(x => x.name).join(', '), '');
if (rec.risk_flags?.length) lines.push('RISK FLAGS: ' + rec.risk_flags.join(', '), '');
lines.push(`(${rec.provenance?.llm_provider}/${rec.provenance?.model} · confidence ${rec.confidence})`);
const summary = lines.join('\n');
const subject = 'Call Summary - ' + (rec.account.name || 'Unknown Account');

const J = { 'Content-Type': 'application/json' };
let _req;
switch (c.crm_provider) {
  case 'zoho':       // NOTE: region-specific domain (.com/.eu/.in/.com.au) via CRM_BASE_URL
    _req = { url: (c.crm_base || 'https://www.zohoapis.com') + '/crm/v5/Calls',
      headers: { ...J, Authorization: 'Zoho-oauthtoken ' + c.crm_token },
      body: { data: [{ Subject: subject, Description: summary,
        Call_Start_Time: rec.start_time, Call_Type: 'Inbound', Call_Duration: '00:30' }] } };
    break;
  case 'hubspot':
    _req = { url: 'https://api.hubapi.com/crm/v3/objects/calls',
      headers: { ...J, Authorization: 'Bearer ' + c.crm_token },
      body: { properties: { hs_call_title: subject, hs_call_body: summary,
        hs_timestamp: rec.start_time, hs_call_direction: 'INBOUND' } } };
    break;
  case 'salesforce':
    _req = { url: (c.crm_base || '') + '/services/data/v60.0/sobjects/Task',
      headers: { ...J, Authorization: 'Bearer ' + c.crm_token },
      body: { Subject: subject, Description: summary, Status: 'Completed', TaskSubtype: 'Call' } };
    break;
  case 'pipedrive':
    _req = { url: (c.crm_base || 'https://api.pipedrive.com') + '/v1/notes?api_token=' + c.crm_token,
      headers: J, body: { content: '<b>' + subject + '</b><br>' + summary.replace(/\n/g, '<br>') } };
    break;
  case 'monday': {
    const m = rec._monday;
    if (!m) throw new Error('monday mapping missing - Discover Schema did not run.');
    const cv = JSON.stringify(m.column_values).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
    const grp = m.group_id ? `group_id: "${m.group_id}", ` : '';
    _req = { url: 'https://api.monday.com/v2',
      headers: { ...J, Authorization: c.crm_token, 'API-Version': '2024-10' },
      body: { query: `mutation { create_item (board_id: ${m.board_id}, ${grp}` +
        `item_name: "${m.item_name.replace(/"/g, '\\"')}", ` +
        `column_values: "${cv}") { id } }` } };
    break;
  }
  default:           // generic webhook - canonical record, untouched
    _req = { url: c.crm_webhook, headers: J, body: rec };
}
if (!_req.url) throw new Error('No CRM target configured. Set CRM_WEBHOOK_URL or CRM_PROVIDER + CRM_BASE_URL.');
return [{ json: { ...rec, _req } }];

// monday has NO standard fields - every board is user-defined columns.
// So we cannot hardcode a mapping; we must introspect. This is the same
// introspection the Board Audit workflow uses.
const c = $('Runtime Config').first().json._cfg;
if (c.crm_provider !== 'monday') return [{ json: { ...$json, _skip_discovery: true } }];
if (!c.monday_board) throw new Error('MONDAY_BOARD_ID not set.');

return [{ json: { ...$json, _req: {
  url: 'https://api.monday.com/v2',
  headers: { 'Content-Type': 'application/json', Authorization: c.crm_token,
             'API-Version': '2024-10' },
  body: { query: `query { boards(ids: [${c.monday_board}]) { id name
            columns { id title type settings_str }
            groups { id title } } }` }
} }}];

// Map canonical record -> this board's actual column ids.
// Deterministic synonym + type matching. Reliable, debuggable, no LLM needed here.
const c = $('Runtime Config').first().json._cfg;
const rec = $('Validate Extraction').first().json;
const resp = $json;

if (c.crm_provider !== 'monday') return [{ json: rec }];

const board = resp?.data?.boards?.[0];
if (!board) throw new Error('monday board not found or token lacks access.');
const cols = board.columns || [];

const norm = s => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const SYNONYMS = {
  summary:      ['summary','callsummary','notes','callnotes','description','details'],
  commitments:  ['commitments','repcommitments','promised','followups','owed'],
  next_steps:   ['nextsteps','nextstep','actions','actionitems','todo'],
  objections:   ['objections','concerns','blockers'],
  pain_points:  ['painpoints','pain','challenges','problems','needs'],
  competitors:  ['competitors','competition','competitor','vsvendor'],
  risk:         ['risk','riskflags','dealrisk','healthflags'],
  stage:        ['stage','status','dealstage','pipelinestage'],
  timeline:     ['timeline','closedate','expectedclose','targetdate'],
  confidence:   ['confidence','aiconfidence','score'],
  account:      ['account','company','organisation','organization','client','customer']
};
const findCol = (key, allowed) => {
  const wants = SYNONYMS[key] || [];
  return cols.find(col => wants.includes(norm(col.title)) &&
                          (!allowed || allowed.includes(col.type)));
};

const bullets = (arr, f) => (arr || []).map(x => '• ' + f(x)).join('\n');
const summary = [
  rec.rep_commitments?.length ? 'COMMITMENTS BY REP:\n' +
    bullets(rec.rep_commitments, x => x.commitment + (x.due ? ' (due ' + x.due + ')' : '')) : '',
  rec.next_steps?.length ? 'NEXT STEPS:\n' +
    bullets(rec.next_steps, x => x.action + ' [' + (x.owner || 'unassigned') + ']') : '',
  rec.objections?.length ? 'OBJECTIONS:\n' + bullets(rec.objections, x => x.objection) : '',
  rec.pain_points?.length ? 'PAIN POINTS:\n' + bullets(rec.pain_points, x => x.paraphrase) : '',
  rec.competitors_mentioned?.length ?
    'COMPETITORS: ' + rec.competitors_mentioned.map(x => x.name).join(', ') : '',
  rec.risk_flags?.length ? 'RISK: ' + rec.risk_flags.join(', ') : ''
].filter(Boolean).join('\n\n');

const TEXTY = ['text','long_text'];
const values = {}; const mapped = []; const unmapped = [];
const put = (key, val, allowed) => {
  const col = findCol(key, allowed);
  if (col) { values[col.id] = val; mapped.push(`${key} -> ${col.title} (${col.id})`); }
  else unmapped.push(key);
};

put('summary',     summary, TEXTY);
put('commitments', bullets(rec.rep_commitments, x => x.commitment), TEXTY);
put('next_steps',  bullets(rec.next_steps, x => x.action), TEXTY);
put('objections',  bullets(rec.objections, x => x.objection), TEXTY);
put('pain_points', bullets(rec.pain_points, x => x.paraphrase), TEXTY);
put('competitors', (rec.competitors_mentioned || []).map(x => x.name).join(', '), TEXTY);
put('risk',        (rec.risk_flags || []).join(', '), TEXTY);
put('confidence',  rec.confidence, ['numbers']);

const stageCol = findCol('stage', ['status','color']);
if (stageCol && rec.recommended_stage) {
  values[stageCol.id] = { label: rec.recommended_stage };
  mapped.push(`stage -> ${stageCol.title} (${stageCol.id})`);
} else if (rec.recommended_stage) unmapped.push('stage');

return [{ json: { ...rec, _monday: {
  board_id: board.id, board_name: board.name,
  group_id: c.monday_group || board.groups?.[0]?.id || '',
  item_name: 'Call - ' + (rec.account.name || 'Unknown') + ' - ' +
             new Date(rec.start_time).toISOString().slice(0,10),
  column_values: values,
  // surfaced deliberately: unmapped fields ARE the audit finding
  mapping_report: { mapped, unmapped,
    note: unmapped.length ? 'Board has no column for: ' + unmapped.join(', ') +
          '. Extraction is richer than the board can store.' : 'All fields mapped.' }
} }}];

// VALIDATOR - runs between the model and the CRM. Nothing reaches the CRM adapter
// unless it passes here AND clears the confidence threshold.
//
// The model's own confidence number is self-reported, so it is not treated as
// evidence. These checks compare the extraction against the transcript itself:
//   - shape:        required fields exist and have the right types
//   - quotes:       a verbatim_quote must be an exact substring of the transcript
//   - competitors:  the name must appear in the transcript as whole words
//   - commitments:  every number in a rep commitment must appear in the transcript,
//                   and at least half of its content words must too (compared as
//                   whole words with common endings removed). A heuristic: it
//                   catches inventions, it does not prove a paraphrase is faithful.
//   - due dates:    a due value must be made of words from the transcript
// Anything that fails a hard check is moved to _quarantined and the whole record
// is routed to human review. Ungrounded quotes and due dates are stripped and
// flagged (soft).
const rec = $json;
const segments = $('Normalize Transcript').first().json.segments || [];

const norm = (s) => String(s || '').toLowerCase()
  .replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
  .replace(/\s+/g, ' ').trim();
const transcript = norm(segments.map((s) => s.text).join(' '));

// Whole-word matching: "Clari" must not be grounded by "clarify", nor "rate" by "separate".
const tokens = (s) => norm(s).replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean);
const stem = (w) => { const m = /^(.{4,}?)(ing|ed|es|s|e)$/.exec(w); return m ? m[1] : w; };
const said = tokens(transcript);
const saidWords = new Set(said);
const saidStems = new Set(said.map(stem));
const saidText = ' ' + said.join(' ') + ' ';
const saysPhrase = (s) => { const t = tokens(s); return t.length > 0 && saidText.includes(' ' + t.join(' ') + ' '); };

const STOP = new Set(['that', 'this', 'with', 'from', 'will', 'have', 'they', 'them', 'their',
  'your', 'about', 'what', 'when', 'were', 'been', 'would', 'could', 'should', 'into', 'over',
  'send', 'sent', 'next', 'week', 'follow', 'call', 'team', 'customer', 'prospect']);
const contentWords = (s) => tokens(s).filter((w) => w.length > 3 && !STOP.has(w) && !/\d/.test(w));
const numbers = (s) => tokens(s).filter((w) => /\d/.test(w));

const flags = [];
const hard = (code, detail) => flags.push({ code, severity: 'hard', detail });
const soft = (code, detail) => flags.push({ code, severity: 'soft', detail });

// --- shape ---------------------------------------------------------------
const ARRAYS = ['attendees', 'pain_points', 'competitors_mentioned', 'objections',
  'rep_commitments', 'next_steps', 'risk_flags'];
for (const key of ARRAYS) {
  if (!Array.isArray(rec[key])) hard('schema_invalid', key + ' is not an array');
}
if (!rec.account || typeof rec.account.name !== 'string') hard('schema_invalid', 'account.name missing');
const conf = typeof rec.confidence === 'number' ? rec.confidence : NaN;
if (!Number.isFinite(conf) || conf < 0 || conf > 1) hard('schema_invalid', 'confidence is not a number between 0 and 1');

const arr = (key) => (Array.isArray(rec[key]) ? rec[key] : []);
const quarantined = { rep_commitments: [], competitors_mentioned: [] };

// --- quotes (soft: strip the quote, keep the paraphrase) -------------------
const painPoints = arr('pain_points').map((p) => {
  if (p && p.verbatim_quote && !transcript.includes(norm(p.verbatim_quote))) {
    soft('ungrounded_quote', String(p.verbatim_quote).slice(0, 120));
    return { ...p, verbatim_quote: '' };
  }
  return p;
});

// --- competitors (hard) ---------------------------------------------------
const competitors = arr('competitors_mentioned').filter((c) => {
  if (saysPhrase(c && c.name)) return true;
  quarantined.competitors_mentioned.push(c);
  hard('ungrounded_competitor', String((c && c.name) || '(empty)'));
  return false;
});

// --- rep commitments (hard) -----------------------------------------------
const MIN_OVERLAP = 0.5;
const quarantine = (c, code, detail) => {
  quarantined.rep_commitments.push(c); hard(code, detail); return false; };
const commitments = arr('rep_commitments').filter((c) => {
  const text = c && c.commitment;
  const words = contentWords(text);
  if (!words.length) return quarantine(c, 'empty_commitment', 'commitment has no checkable content');
  const found = words.filter((w) => saidWords.has(w) || saidStems.has(stem(w))).length;
  if (found / words.length < MIN_OVERLAP) return quarantine(c, 'ungrounded_commitment', String(text).slice(0, 120));
  const missing = numbers(text).filter((n) => !saidWords.has(n));
  if (missing.length) return quarantine(c, 'ungrounded_number', missing.join(', ') + ' in: ' + String(text).slice(0, 100));
  return true;
}).map((c) => {
  // due dates (soft: strip the date, keep the commitment)
  if (c.due && !tokens(c.due).every((w) => saidWords.has(w))) {
    soft('ungrounded_due', String(c.due).slice(0, 60));
    return { ...c, due: '' };
  }
  return c;
});

// --- pipeline health ------------------------------------------------------
const failed = Number(rec.provenance && rec.provenance.chunks_failed) || 0;
if (failed > 0) hard('chunk_parse_failures', failed + ' chunk(s) returned unparseable output');
if (!commitments.length && !arr('next_steps').length && !painPoints.length) {
  hard('empty_extraction', 'no commitments, next steps or pain points were extracted');
}

const passed = !flags.some((f) => f.severity === 'hard');
const minConf = Number(rec._min_confidence);
const clearsConfidence = Number.isFinite(conf) && conf >= (Number.isFinite(minConf) ? minConf : 0.6);

return [{ json: {
  ...rec,
  pain_points: painPoints,
  competitors_mentioned: competitors,
  rep_commitments: commitments,
  _quarantined: quarantined,
  validation: { passed, clears_confidence: clearsConfidence, flags,
    checks: ['shape', 'quotes', 'competitors', 'commitments', 'due_dates', 'pipeline_health'] },
  _gate: passed && clearsConfidence ? 1 : 0 } }];
